from dataclasses import dataclass, field


class InvalidDiscount(ValueError):
    """The order's discount percent is outside the allowed 0-100 range."""


@dataclass
class OrderLine:
    sku: str
    qty: int
    unit_cents: int

    @property
    def total_cents(self) -> int:
        return self.qty * self.unit_cents


@dataclass
class Order:
    id: str
    lines: list[OrderLine] = field(default_factory=list)
    currency: str = "USD"
    discount_percent: int = 0

    def __post_init__(self):
        if self.discount_percent < 0 or self.discount_percent > 100:
            raise InvalidDiscount(
                f"order {self.id}: discount_percent must be 0-100 (got {self.discount_percent})")

    @property
    def subtotal_cents(self) -> int:
        return sum(line.total_cents for line in self.lines)

    @property
    def discount_cents(self) -> int:
        """Amount taken off by the percentage discount, rounded down to whole cents."""
        return self.subtotal_cents * self.discount_percent // 100

    @property
    def total_cents(self) -> int:
        return self.subtotal_cents - self.discount_cents
